-- 既有住宅小区车位情况统计表 数据（数据源：金山文档《既有住宅小区车位情况统计表》）
-- 只保留寺家庄镇，共 18 条
DELETE FROM `parking`;
ALTER TABLE `parking` AUTO_INCREMENT = 1;


-- 按小区名称自动关联本系统小区
UPDATE `parking` p JOIN `community` c ON p.`community_name` = c.`name`
   SET p.`community_id` = c.`id`;

-- 别名关联（统计表与系统小区名称叫法不同）
UPDATE `parking` p JOIN `community` c ON c.`name`='柠檬小镇' SET p.`community_id` = c.`id` WHERE p.`community_name`='柠檬小区';
UPDATE `parking` p JOIN `community` c ON c.`name`='四季阳光' SET p.`community_id` = c.`id` WHERE p.`community_name`='四季阳光城';
UPDATE `parking` p JOIN `community` c ON c.`name`='万和华府' SET p.`community_id` = c.`id` WHERE p.`community_name`='万合华府';
UPDATE `parking` p JOIN `community` c ON c.`name`='长久广场' SET p.`community_id` = c.`id` WHERE p.`community_name`='长九广场';
UPDATE `parking` p JOIN `community` c ON c.`name`='城果小区' SET p.`community_id` = c.`id` WHERE p.`community_name`='城果二期（城果小区）';
UPDATE `parking` p JOIN `community` c ON c.`name`='富强南院' SET p.`community_id` = c.`id` WHERE p.`community_name`='富强家园南院';
